for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
    rel=f'sources/{tree}/fr/236.tex'
    def r(a,b,line,why,kind='reading',count=1):
        replace(rel,a,b,layer,'236-223',line,'1',
                'Scan leaf 4 at 400 dpi, full page and three enlarged bands: '+why,kind=kind,count=count)
    r('G^\\sigma=\\bigcup_{(n,p)=1}G^{(n)},\n\\qquad\nG^\\rho=\\bigcup_hG^{(p^h)},', '\\begin{gathered}\nG^\\sigma=\\bigcup_{(n,p)=1}G^{(n)}\\\\[6pt]\nG^\\rho=\\bigcup_hG^{(p^h)}\n\\end{gathered}', 'opening definitions','The two equalities occupy separate centered lines with no commas.','structure')
    r(r'G^\sigma G^\rho=G^\tau.',r'G^\sigma\cdot G^\rho=G^\tau.','product identity','A centered multiplication dot is printed between the factors.')
